import sys, json, subprocess, os, tempfile
sys.path[:0] = [sys.argv[1], sys.argv[2]]
from ln import ln_syntax_spec
from caruca.ir.syntax import Flag, Selection, Path, String
opts, pos = ln_syntax_spec[0]
tbl = json.load(open(os.path.join(sys.argv[2], 'annotation/ln.json')))
flags = {s for e in tbl['flag'] for s in ([e] if isinstance(e,str) else e)}
options = {s for e in tbl['option'] for s in e[:-1]}
# consistency between syntax spec and json table
spec_flags = {s for n in opts if isinstance(n, Flag) for s in n.spellings()}
spec_opts = {s for n in opts if not isinstance(n, Flag) for s in n.spellings()}
assert spec_flags == flags, (spec_flags ^ flags)
assert spec_opts == options, (spec_opts ^ options)
print("spec/json consistent:", len(flags), "flag spellings,", len(options), "option spellings")
# every spelling accepted by real ln
d = tempfile.mkdtemp(); os.chdir(d); open('a','w').write('x'); os.mkdir('dir')
bad=[]
for s in sorted(flags - {'--help','--version','-i','--interactive'}):
    r = subprocess.run(['ln', s, '-s', 'a', 'l'], capture_output=True, text=True); os.path.lexists('l') and os.remove('l')
    if 'unrecognized' in r.stderr or 'invalid option' in r.stderr: bad.append((s, r.stderr))
for n in opts:
    if isinstance(n, Flag): continue
    for s in n.spellings():
        val = {'--backup':'numbered','-S':'.bak','--suffix':'.bak','-t':'dir','--target-directory':'dir'}[s]
        args = [s+'='+val] if n.kw.get('flag_followed_by_equals') or s.startswith('--') else [s, val]
        r = subprocess.run(['ln','-sf',*args,'a'] + ([] if s in('-t','--target-directory') else ['l']), capture_output=True, text=True)
        if r.returncode: bad.append((s, r.stderr))
    if isinstance(n, Selection):
        for c in n.kw['choices']:
            r = subprocess.run(['ln','-sf', n.flag + ('='+c if c else ''), 'a','l'], capture_output=True, text=True)
            if r.returncode: bad.append((c, r.stderr))
print("binary rejected:", bad or "nothing")
# unknown-option check: a letter not in our table must be rejected by ln
import string
for ch in string.ascii_letters:
    r = subprocess.run(['ln', '-'+ch, 'a', 'l'], capture_output=True, text=True); os.path.lexists('l') and os.remove('l')
    known = ('-'+ch) in flags|options
    rejected = 'invalid option' in r.stderr
    if known == rejected: print("MISMATCH short option", ch, known, r.stderr.strip())
print("short-option sweep done")
# simulate PaSh parser on sample invocations
def parse(words):
    fo=[]; ops=[]; it=iter(words)
    for w in it:
        if w in flags: fo.append((w,))
        elif w in options: fo.append((w,next(it)))
        elif '=' in w and w.split('=')[0] in options: fo.append(tuple(w.split('=',1)))
        elif w.startswith('-') and len(w)>2 and not w.startswith('--') and all('-'+c in flags for c in w[1:]): fo += [('-'+c,) for c in w[1:]]
        else: ops=[w]+list(it); break
    return fo, ops
for inv in ["ln a l1","ln -s a l2","ln -sT a l3","ln a b d","ln -ft d a b","ln --target-directory=d -f a","ln -sfb -S .bak a l1","ln -sf --backup=numbered a l1","ln -s --relative a d/l4","ln -s a -"]:
    print(inv, "->", parse(inv.split()[1:]))
EOF
